<template><div class="page"><el-card><template #header><div style="display:flex;justify-content:space-between"><span>短信配置</span><el-button type="primary" size="small" @click="showDialog=true">新增配置</el-button></div></template><el-table :data="list" border><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="platform" label="平台" width="120"/><el-table-column prop="sign_name" label="签名"/><el-table-column prop="template_code" label="模板编码"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'" size="small">{{row.status===1?'启用':'禁用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button size="small" @click="edit(row)">编辑</el-button><el-button size="small" type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="showDialog" :title="form.id?'编辑配置':'新增配置'" width="600px"><el-form :model="form" label-width="100px"><el-form-item label="平台"><el-select v-model="form.platform"><el-option label="阿里云" value="aliyun"/><el-option label="腾讯云" value="tencent"/><el-option label="华为云" value="huawei"/></el-select></el-form-item><el-form-item label="AccessKey"><el-input v-model="form.access_key"/></el-form-item><el-form-item label="SecretKey"><el-input v-model="form.secret_key" type="password" show-password/></el-form-item><el-form-item label="签名"><el-input v-model="form.sign_name"/></el-form-item><el-form-item label="模板编码"><el-input v-model="form.template_code"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item></el-form><template #footer><el-button @click="showDialog=false">取消</el-button><el-button type="primary" @click="submit">确定</el-button></template></el-dialog></div></template><script setup>import{ref,reactive,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import request from'@/utils/request';const list=ref([]);const showDialog=ref(false);const form=reactive({id:null,platform:'aliyun',access_key:'',secret_key:'',sign_name:'',template_code:'',status:1});const loadList=async()=>{const res=await request({url:'/sms-configs'});list.value=res.data||[]};const edit=(row)=>{Object.assign(form,row);showDialog.value=true};const remove=async(row)=>{await ElMessageBox.confirm('确定删除？','提示',{type:'warning'});await request({url:`/sms-configs/${row.id}`,method:'delete'});ElMessage.success('删除成功');loadList()};const submit=async()=>{if(form.id)await request({url:`/sms-configs/${form.id}`,method:'put',data:form});else await request({url:'/sms-configs',method:'post',data:form});ElMessage.success('保存成功');showDialog.value=false;loadList()};onMounted(()=>loadList())</script>
